package com.deardiary.privateapp;
import android.app.Activity;import android.content.*;import android.os.*;import android.view.WindowManager;import android.widget.Toast;import java.net.*;import java.io.*;import java.util.*;import org.json.*;
/** No diary WebView or content. Only the exact reel link is allowed out. */
public final class ReelShareActivity extends Activity{
 static String parse(Intent intent){try{if(!Intent.ACTION_SEND.equals(intent.getAction())||!"text/plain".equals(intent.getType())||intent.hasExtra(Intent.EXTRA_STREAM))return null;CharSequence raw=intent.getCharSequenceExtra(Intent.EXTRA_TEXT);if(raw==null||raw.length()>2048)return null;String[] words=raw.toString().trim().split("\\s+");String reel=null;for(String word:words){if(word.startsWith("http://")||word.startsWith("https://")){String candidate=InstagramReelUrl.clean(word);if(candidate==null||reel!=null)return null;reel=candidate;}}return reel;}catch(Exception e){return null;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);if(b!=null){finish();return;}String url=parse(getIntent());if(url==null){notice("Could not send. Share one Instagram reel link only.");return;}if(((android.app.KeyguardManager)getSystemService(KEYGUARD_SERVICE)).isKeyguardLocked()){notice("Could not send. Unlock your phone first.");return;}if(getSharedPreferences("push",0).getBoolean("friend_mode",false)){notice("Could not send in Friend mode.");return;}if(!ReelShareStore.enabled(this)){notice("Could not send. Enable quick reel sharing in Dear Diary Settings first.");return;}final String request=UUID.randomUUID().toString();new Thread(()->{HttpURLConnection connection=null;String message="Could not confirm sending. Check Chat before sharing again.";try{String token=ReelShareStore.read(this);connection=(HttpURLConnection)new URL("https://etkjcywiaiiphsrthxqe.supabase.co/functions/v1/reel-quick-share").openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(15000);connection.setRequestMethod("POST");connection.setRequestProperty("Content-Type","application/json");connection.setRequestProperty("Authorization","Bearer "+token);connection.setDoOutput(true);byte[] body=new JSONObject().put("url",url).put("request",request).toString().getBytes("UTF-8");connection.setFixedLengthStreamingMode(body.length);try(OutputStream out=connection.getOutputStream()){out.write(body);}int status=connection.getResponseCode();if(status==200){try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] response=new byte[128];int n;while((n=in.read(response))!=-1){if(out.size()+n>512)throw new IOException();out.write(response,0,n);}if(new JSONObject(out.toString("UTF-8")).optBoolean("ok"))message="Reel link sent to your linked chat.";}}else{message="Could not send. Check quick-share setup and try again.";}}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();final String result=message;runOnUiThread(()->notice(result));}},"reel-share").start();}
 private void notice(String message){Toast.makeText(getApplicationContext(),message,Toast.LENGTH_LONG).show();finish();}
}
